class Myloss(nn.Module):

    def __init__(self, epsilon=1e-08):
        super(Myloss, self).__init__()
        self.epsilon = epsilon
        return

    def forward(self, input_, label, weight):
        entropy = -label * torch.log(input_ + self.epsilon) - (1 - label
